        self.spy = self.symbols["SPY"]
        self.aapl = self.symbols["AAPL"]

        self.sma = self.SMA(self.spy, 20, Resolution.Daily)
        self.rsi = self.RSI(self.aapl, 14, Resolution.Daily, MovingAverageType.Wilders)

        self.prev_spy_close = None
        self.prev_sma_value = None
        self.prev_aapl_close = None
        self.aapl_red_streak = 0

        self.a_shares = 0
        self.b_shares = 0

    def OnData(self, data: Slice):
        for symbol in self.symbols.values():
            if symbol not in data.Bars:
                return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close

        self._run_strategy_a(spy_close)
        self._run_strategy_b(aapl_close)

    def _run_strategy_a(self, spy_close):
        if not self.sma.IsReady:
            return
        sma_value = self.sma.Current.Value

        crossed_above = False
        crossed_below = False
        if self.prev_spy_close is not None and self.prev_sma_value is not None:
            crossed_above = self.prev_spy_close <= self.prev_sma_value and spy_close > sma_value
            crossed_below = self.prev_spy_close >= self.prev_sma_value and spy_close < sma_value

        if self.a_shares > 0:
            if crossed_below:
                self.MarketOrder(self.spy, -self.a_shares)
                self.a_shares = 0
        elif crossed_above:
            target_value = 0.40 * self.Portfolio.TotalPortfolioValue
            shares = int(target_value // spy_close)
            if shares > 0:
                self.MarketOrder(self.spy, shares)
                self.a_shares = shares

        self.prev_spy_close = spy_close
        self.prev_sma_value = sma_value

    def _run_strategy_b(self, aapl_close):
        is_red = self.prev_aapl_close is not None and aapl_close < self.prev_aapl_close
        self.aapl_red_streak = self.aapl_red_streak + 1 if is_red else 0
        self.prev_aapl_close = aapl_close

        if self.b_shares > 0:
            if self.rsi.IsReady and self.rsi.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.b_shares)
                self.b_shares = 0
        elif self.aapl_red_streak >= 3:
            cash = self.Portfolio.Cash
            if cash >= 20000:
                shares = int(20000 // aapl_close)
                if shares > 0:
                    self.MarketOrder(self.aapl, shares)
                    self.b_shares = shares

